[CmdletBinding()]
param([string]$ProjectPath=(Get-Location).Path,[ValidateSet('New','Existing')][string]$ProjectKind='Existing',[string]$StudioVersion,[string]$RobotVersion,[string]$CliVersion,[string]$CliPath,[string[]]$AvailableUiAutomationVersion=@(),[string[]]$RequiredCapability=@(),[string]$CompatibilityEvidencePath,[switch]$NewerReleaseCompatibilityEstablished,[string]$OutputPath,[switch]$Json,[string[]]$AdditionalPackageRoots=@())
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'UiPathCompatibility.psm1') -Force
$result=Get-UiPathEnvironmentCompatibility -ProjectPath $ProjectPath -ProjectKind $ProjectKind -StudioVersion $StudioVersion -RobotVersion $RobotVersion -CliVersion $CliVersion -CliPath $CliPath -AvailableUiAutomationVersion $AvailableUiAutomationVersion -RequiredCapability $RequiredCapability -CompatibilityEvidencePath $CompatibilityEvidencePath -NewerReleaseCompatibilityEstablished:$NewerReleaseCompatibilityEstablished -AdditionalPackageRoots $AdditionalPackageRoots
if($OutputPath){$full=if([IO.Path]::IsPathRooted($OutputPath)){[IO.Path]::GetFullPath($OutputPath)}else{[IO.Path]::GetFullPath((Join-Path $ProjectPath $OutputPath))};New-Item -ItemType Directory -Force -Path (Split-Path $full -Parent)|Out-Null;[IO.File]::WriteAllText($full,(($result|ConvertTo-Json -Depth 12)+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false)))}
if($Json){$result|ConvertTo-Json -Depth 12}else{$result}
